<script setup lang="ts">
/**
 * The conversation screen, with a thread above a composer (`design/archetypes/conversation-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/conversation-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef } from 'vue'

import { devWarning, useTrackedSlots } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/conversation-page.module.css'
import Button from '../controls/Button.vue'
import Drawer from '../overlays/Drawer.vue'
import PageHeader from '../structure/PageHeader.vue'
import SplitPane from '../layout/SplitPane.vue'

export interface ConversationPageProps {
  /**
   * The aside's name, used for the separator, the drawer's title and the toggle's label.
   */
  asideLabel?: string
  description?: string
  title: string
}

defineOptions({ name: 'ConversationPage', inheritAttrs: false })

const props = defineProps<ConversationPageProps>()
const callerSlots = defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  aside?: (props: Record<string, never>) => unknown
  composer: (props: Record<string, never>) => unknown
  thread: (props: Record<string, never>) => unknown
}>()
const slots = useTrackedSlots(callerSlots)
const narrow = ref(false)
const asideOpen = ref(false)
const root = useTemplateRef<HTMLElement>('root')
const measure = computed(() => () => {
  if (root.value === null) return
  const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
  const below = root.value.getBoundingClientRect().width < 48 * rem
  narrow.value = below
  if (!below) asideOpen.value = false
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure.value()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  devWarning(
    Boolean(slots.aside) && props.asideLabel === undefined,
    'ConversationPage: an `aside` needs an `asideLabel`, which names the split’s separator, the drawer and its toggle.',
  )
}
onMounted(effect2)
</script>

<template>
  <div
    ref="root"
    :class="styles.page"
    :data-aside="$slots.aside ? (narrow ? 'drawer' : 'split') : undefined"
    data-member="conversation-page"
  >
    <PageHeader :title="title" :description="description">
      <template v-if="$slots.actions || ($slots.aside && narrow)" #actions>
        <slot name="actions" />
        <Button
          v-if="$slots.aside && narrow"
          variant="outline"
          tone="neutral"
          size="sm"
          icon="artifact"
          :label="asideLabel ?? ''"
          @click="asideOpen = true"
        />
      </template>
    </PageHeader>
    <!-- body -->
    <div :class="styles.body">
      <SplitPane
        v-if="$slots.aside && !narrow"
        :label="asideLabel ?? ''"
        :defaultRatio="0.58"
        :startMin="320"
        :endMin="280"
      >
        <template #start>
          <!-- conversation -->
          <div :class="styles.conversation">
            <!-- thread -->
            <div :class="styles.thread">
              <slot name="thread" />
            </div>
            <!-- composer -->
            <div :class="styles.composer">
              <slot name="composer" />
            </div>
          </div>
        </template>
        <template #end>
          <!-- aside -->
          <div :class="styles.aside">
            <slot name="aside" />
          </div>
        </template>
      </SplitPane>
      <!-- conversation -->
      <div v-else :class="styles.conversation">
        <!-- thread -->
        <div :class="styles.thread">
          <slot name="thread" />
        </div>
        <!-- composer -->
        <div :class="styles.composer">
          <slot name="composer" />
        </div>
      </div>
    </div>
    <Drawer
      v-if="$slots.aside && narrow"
      side="end"
      size="lg"
      :title="asideLabel ?? ''"
      :open="asideOpen"
      @openChange="asideOpen = $event"
    >
      <!-- drawerAside -->
      <div :class="styles.drawerAside">
        <slot name="aside" />
      </div>
    </Drawer>
  </div>
</template>
